package org.millenaire.common.village;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import java.util.*;import org.millenaire.common.utilities.Point;public class Building {public Map<Block,Integer> stocks=new HashMap<>();public int reportedExtra=0;public int countGoods(BlockState s){return stocks.getOrDefault(s.getBlock(),0)+reportedExtra;}public int takeGoods(BlockState s,int n){int taken=Math.min(n,stocks.getOrDefault(s.getBlock(),0));stocks.merge(s.getBlock(),-taken,Integer::sum);return taken;}public static class Resources{public List<Point> furnaces=new ArrayList<>(),firepits=new ArrayList<>();}public Resources resources=new Resources();public Resources getResManager(){return resources;}}